-- [WARNING] 배포 DB(iksanshop) 실행 전 주의사항
-- 이 스크립트는 categories/products 테이블에 데이터를 단순 INSERT 합니다.
-- 기존 orders/gifts 테이블의 product_id 참조가 깨지지 않도록 (중복 생성 방지),
-- 스크립트 실행 전 아래 쿼리로 기존 데이터 존재 여부를 반드시 확인하세요:
-- SELECT COUNT(*) FROM products;
-- 만약 데이터가 이미 존재한다면 실행을 중단하거나 수동 판단 하에 진행하세요.
--
-- [카테고리 매핑 기준] db/migrate_categories.sql 상단 주석 참고 (팀 논의로 확정되기
-- 전까지 상품명 기준 6개 카테고리로 임시 매핑).
--
-- [상세정보 컬럼 안내] db/migrate_product_detail_fields.sql로 usage_info가
-- valid_period/usage_method/exchange_location/caution 4개로 분리되었습니다.
-- 이슈 #68 논의(전 상품 매장 교환형 통일)에 따라 4개 컬럼 전부 채웠습니다.
-- - valid_period: 전 상품 공통 "발급일로부터 365일"
-- - usage_method: "교환권 제시 후 매장에서 OO으로 교환 가능합니다" 패턴(기존에
--   이미 교환권형이던 8개 상품은 기존 문구 유지, 그 외 25개는 새로 작성)
-- - exchange_location: 상품별 brand 값을 그대로 사용
-- - caution: 전 상품 공통 취소·환불 안내(익산 기프트 자체 정책, 바코드 사용
--   전/후 기준)
-- 배송형처럼 보이던 25개 상품은 매장 교환형과 자연스럽게 맞도록 name도 함께
-- "OO 교환권" 형태로 변경했습니다(description은 범위 밖, 별도 진행 예정).
--
-- [설명 이미지 컬럼 안내] db/migrate_product_description_image.sql로 추가된
-- description_image_url은 이슈 #56 논의에 따라 값 채우기를 FE/배포 담당자가
-- 진행하므로, 아래 INSERT문에는 포함하지 않고 NULL 기본값으로 둡니다.

INSERT INTO categories (name) VALUES
('음료'),
('베이커리·간식'),
('축산·농산물'),
('외식·상품권'),
('체험·관광이용권'),
('지역특산 선물세트');

